import { checkpoint } from "@tigrisdata/agent-kit";
import fs from "fs";
import path from "path";

const trialIdPath = "/logs/artifacts/trial_id";
const buildIdPath = path.join(__dirname, "build_id.txt");
const snapshotPath = path.join(__dirname, "snapshot.json");

const buildId = fs.readFileSync(buildIdPath, "utf8").trim();
if (!buildId) {
  throw new Error("Build id is empty");
}

const trialIdRaw = fs.readFileSync(trialIdPath, "utf8").trim();
if (!trialIdRaw) {
  throw new Error("Trial id is empty");
}

const trialIdNormalized = trialIdRaw.toLowerCase().replace(/[^a-z0-9-]/g, "-");
const bucketName = `harbor-pipeline-${trialIdNormalized}`;
const unixTimestamp = Math.floor(Date.now() / 1000);
const name = `release-${buildId}-${unixTimestamp}`;

const result = await checkpoint(bucketName, { name });
if (result.error) {
  throw result.error;
}

const snapshotId = result.data?.snapshotId;
if (!snapshotId) {
  throw new Error("Checkpoint did not return snapshotId");
}

const payload = {
  snapshotId,
  name,
};

fs.writeFileSync(snapshotPath, JSON.stringify(payload, null, 2));

