const bucketCandidates = [
  `harbor-pipeline-${trialIdRaw
    .toLowerCase()
    .replace(/[^a-z0-9-]/g, "-")}`,
  `harbor-pipeline-${trialIdRaw
    .toLowerCase()
    .replace(/[^a-z0-9_]/g, "-")}`,
  `harbor-pipeline-${trialIdRaw.toLowerCase()}`,
  `harbor-pipeline-${trialIdRaw}`,
];

const unixTimestamp = Math.floor(Date.now() / 1000);
const name = `release-${buildId}-${unixTimestamp}`;

let checkpointResult = null as Awaited<ReturnType<typeof checkpoint>> | null;
let lastError: Error | null = null;

for (const bucketName of bucketCandidates) {
  const result = await checkpoint(bucketName, { name });
  if (!result.error) {
    checkpointResult = result;
    break;
  }

  lastError = result.error;
}

if (!checkpointResult?.data) {
  throw lastError ?? new Error("Failed to create checkpoint");
}

const snapshotId = checkpointResult.data.snapshotId;
